// ppwr - one output item per campaign item, carrying what the token needs
//
// The expiry is computed once here rather than per node, so every token in a launch shares an
// expiry and a re-run cannot produce two different windows for the same item.

const response = $input.first().json;
if (!response.ok) throw new Error(`Store query failed: ${JSON.stringify(response.error)}`);

const config = $('Configuration').first().json;
const ttlDays = Number(config.token_ttl_days || 45);
const expiresMs = Date.now() + ttlDays * 24 * 60 * 60 * 1000;

const rows = response.rows || [];
if (rows.length === 0) return [{ json: { _empty: true } }];

return rows.map((row) => ({
  json: {
    campaign_item_id: row.campaign_item_id,
    campaign_id: row.campaign_id,
    item_id: row.item_id,
    state: row.state,
    expires_ms: expiresMs,
    expires_at: new Date(expiresMs).toISOString(),
    // The exact bytes the signature covers. Kept as its own field so the verifier in 02 can
    // rebuild it without re-deriving the format from the token.
    token_payload: `${row.campaign_item_id}|${expiresMs}`,
  },
}));

// ppwr - assemble the link
//
// The Crypto node emits standard base64, and the token goes into a URL, so + / = have to go.
// Only the signature needs converting: a uuid and a millisecond count are already URL safe,
// which is why the token is built from three plain parts rather than base64 encoded whole.

const item = $json;
const signature = String(item.token_sig)
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

const token = `${item.campaign_item_id}.${item.expires_ms}.${signature}`;
const base = String($('Configuration').first().json.form_base_url || '').replace(/\/+$/, '');

return {
  json: Object.assign({}, item, {
    token,
    link: `${base}?t=${token}`,
  }),
};

// ppwr - what the launch did
//
// Links are returned only on a dry run. Once sending is wired they belong in the email and
// nowhere else, because an execution log is not a place to keep working credentials.

const config = $('Configuration').first().json;
// Nothing was minted on the empty branch, and referencing a node that never ran throws.
let minted = [];
try {
  minted = $('Hash token for storage').all().map((entry) => entry.json).filter((m) => m && m.token);
} catch (error) {
  minted = [];
}
const dryRun = config.dry_run !== false;

const incoming = $input.all().map((e) => e.json);
const failures = incoming.filter((r) => r && r.send_failed);
const sent = incoming.filter((r) => r && !r.send_failed && !r._empty);

return [
  {
    json: {
      ok: true,
      campaign_id: config.campaign_id,
      invited: minted.length,
      dry_run: dryRun,
      expires_at: minted.length > 0 ? minted[0].expires_at : null,
      links: dryRun ? minted.map((m) => ({ campaign_item_id: m.campaign_item_id, link: m.link })) : undefined,
      sent: dryRun ? 0 : sent.length,
      send_failures: failures.map((f) => ({ contact_email: f.contact_email, error: f.error })),
    },
  },
];

// ppwr - one email per vendor, not one per item
//
// A supplier with forty items gets one message listing forty links. Sending forty separate
// emails is how a compliance campaign gets marked as spam and then ignored.

const minted = $('Hash token for storage').all().map((e) => e.json);
const vendors = $input.all().map((e) => e.json);

const byVendor = new Map();

vendors.forEach((response, index) => {
  const vendor = response && response.row;
  const link = minted[index];
  if (!vendor || !vendor.contact_email || !link) return;

  if (!byVendor.has(vendor.vendor_id)) {
    byVendor.set(vendor.vendor_id, {
      vendor_id: vendor.vendor_id,
      legal_name: vendor.legal_name,
      contact_email: vendor.contact_email,
      contact_name: vendor.contact_name || null,
      links: [],
    });
  }
  byVendor.get(vendor.vendor_id).links.push({
    campaign_item_id: link.campaign_item_id,
    link: link.link,
    expires_at: link.expires_at,
  });
});

// Sorted so a re-run addresses vendors in the same order and two launches diff readably.
const groups = [...byVendor.values()].sort((a, b) => (a.vendor_id < b.vendor_id ? -1 : 1));

return groups.map((group) => {
  const count = group.links.length;
  const plural = count === 1 ? '' : 's';
  const lines = group.links.map((l) => '- ' + l.link).join('\n');
  const greeting = group.contact_name ? 'Dear ' + group.contact_name + ',' : 'Hello,';
  return {
    json: Object.assign({}, group, {
      subject: 'Packaging declaration requested: ' + count + ' item' + plural,
      body: [
        greeting,
        '',
        'We are collecting packaging conformity declarations from our suppliers.',
        'Please complete one short form for each of the ' + count + ' item' + plural + ' below.',
        '',
        lines,
        '',
        'Each link is personal to one item and stops working after ' + group.links[0].expires_at.slice(0, 10) + '.',
        '',
        'This form screens your declaration for completeness and internal consistency. It is not',
        'a conformity assessment, it is not legal advice, and it is not a substitute for a',
        'technical file or a notified body.',
      ].join('\n'),
    }),
  };
});

// ppwr - a send that failed is recorded against the vendor, not lost
//
// The launch continues. The operator sees which address bounced in the summary and in the
// execution list, rather than finding out when a supplier never replies.

return {
  json: {
    send_failed: true,
    vendor_id: $json.vendor_id || null,
    contact_email: $json.contact_email || null,
    error: $json.error ? String($json.error.message || $json.error) : 'unknown send failure',
  },
};
